package io.github.arcadiumclient.runtime.client.optimizations;

import java.lang.reflect.Field;
import java.nio.*;
import java.util.*;
import org.joml.Matrix4f;

public final class PreparedPlayerR2RegressionTest {
    static int checks;
    static void ok(boolean value,String message){checks++;if(!value)throw new IllegalStateException(message);}
    static final class Node {Object box=new Object(),mesh;boolean visible=true,standard=true,finite=true;}
    static final class Parts implements PreparedBlockState073.Parts {Node[] live=new Node[12];int visits;Parts(){Arrays.setAll(live,i->new Node());}public Object part(Object m,int i){visits++;return live[i];}public boolean standard(Object p){return((Node)p).standard;}public boolean finite(Object p){return((Node)p).finite;}public boolean visible(Object p){return((Node)p).visible;}public Object box(Object p){return((Node)p).box;}public Object mesh(Object p){return((Node)p).mesh;}}
    static final class Select implements PreparedBlockState073.Selection {
        Object actor=new Object(),capture=new Object(),backend=new Object(),pass=new Object(),texture="skinA",batch=new Object(),current=actor;boolean active=true,valid=true,switchActor,wrongBatch,invalidateAfterSelect;Runnable effect;int ambient=71,selections;
        public Object current(){return current;}public boolean active(Object a){return active;}public Object capture(Object a){return capture;}public Object backend(Object a){return backend;}public Object pass(Object c){return pass;}public Object texture(Object c){return texture;}public boolean material(Object c,Object m,Object t,Object p){return valid;}
        public Object select(Object d,Object t,Object p){selections++;ambient=3;if(switchActor)current=new Object();if(invalidateAfterSelect)valid=false;if(effect!=null)effect.run();return wrongBatch?new Object():batch;}public int layer(Object d){return ambient;}
        PreparedBlockState073.Material expected(){var e=new PreparedBlockState073.Material();e.actor=actor;e.capture=capture;e.backend=backend;e.pass=pass;e.texture=texture;e.batch=batch;e.model=new Object();return e;}
    }
    static final class Counts implements PreparedBlockState073.Counters {
        int[] size={19,38},count={1,2};int batch=3,device=3;boolean recorded;
        public int size(int i){return size[i];}public int count(int i){return count[i];}public int batch(){return batch;}public int device(){return device;}public boolean recorded(){return recorded;}public void size(int i,int v){size[i]=v;}public void count(int i,int v){count[i]=v;}public void batch(int v){batch=v;}public void device(int v){device=v;}public void recorded(boolean v){recorded=v;}
    }
    static final class Fault extends RuntimeException{}
    static Field field(String name)throws Exception{Field f=GpuPlayerPackets.class.getDeclaredField(name);f.setAccessible(true);return f;}
    static int[] prefix(String name,int count)throws Exception{FloatBuffer f=(FloatBuffer)field(name).get(null);int[] out=new int[count];for(int i=0;i<count;i++)out[i]=Float.floatToRawIntBits(f.get(i));return out;}
    static void shrink(String name,String view,int words)throws Exception{FloatBuffer old=(FloatBuffer)field(name).get(null),small=ByteBuffer.allocateDirect(words*4).order(ByteOrder.nativeOrder()).asFloatBuffer();for(int i=0;i<words;i++)small.put(i,old.get(i));field(name).set(null,small);field(view).set(null,small.duplicate());}
    public static void main(String[] args)throws Throwable{
        Parts parts=new Parts();Object[] expected=parts.live.clone(),boxes=Arrays.stream(parts.live).map(n->n.box).toArray();Object model=new Object();
        ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,0xfff,0)==0x7f,"Body plan");ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,0xfff,1)==0xf80,"Outer plan");
        for(int i=7;i<12;i++){
            Node original=parts.live[i];original.visible=false;int hidden=0xfff&~(1<<i);ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,hidden,1)>=0,"Hidden original");original.visible=true;ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,hidden,1)==-1,"Late reveal silently omitted");original.visible=false;parts.live[i]=new Node();parts.live[i].visible=false;ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,hidden,1)==-1,"Hidden reference replacement suppressed");parts.live[i]=original;original.standard=false;ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,hidden,1)==-1,"Late child/topology ignored");original.standard=true;Object box=original.box;original.box=new Object();ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,hidden,1)==-1,"Changed box ignored");original.box=box;original.mesh=new Object();ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,hidden,1)==-1,"Changed mesh ignored");original.mesh=null;original.visible=true;
        }
        for(int i=7;i<12;i++)parts.live[i].visible=false;parts.visits=0;ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,0x7f,1)==0&&parts.visits==5,"Zero plan was not fully validated");parts.live[11].standard=false;ok(PreparedBlockState073.liveMask(parts,model,expected,boxes,0x7f,1)==-1,"Zero plan skipped new child");
        Select select=new Select();var material=select.expected();ok(PreparedBlockState073.selectOwned(select,material)==3&&select.selections==1&&select.ambient==3,"Ambient layer from nested callback reused");select.current=new Object();int calls=select.selections;ok(PreparedBlockState073.selectOwned(select,material)==Integer.MIN_VALUE&&select.selections==calls,"Wrong actor selected");select.current=select.actor;select.active=false;ok(PreparedBlockState073.selectOwned(select,material)==Integer.MIN_VALUE,"Inactive actor selected");select.active=true;select.valid=false;ok(PreparedBlockState073.selectOwned(select,material)==Integer.MIN_VALUE,"Changed material admitted");select.valid=true;select.switchActor=true;ok(PreparedBlockState073.selectOwned(select,material)==Integer.MIN_VALUE,"Selector reentry changed actor");select.switchActor=false;select.current=select.actor;select.wrongBatch=true;ok(PreparedBlockState073.selectOwned(select,material)==Integer.MIN_VALUE,"Wrong material batch admitted");
        select.wrongBatch=false;select.invalidateAfterSelect=true;ok(PreparedBlockState073.selectOwned(select,material)==Integer.MIN_VALUE,"Material changed during selector accepted");select.invalidateAfterSelect=false;select.valid=true;parts.live[11].standard=true;select.effect=()->parts.live[11].visible=true;ok(PreparedBlockState073.selectOwned(select,material)==3&&PreparedBlockState073.liveMask(parts,model,expected,boxes,0x7f,1)==-1,"Selection callback revealed a part after the earlier plan");select.effect=null;
        GpuPlayerPackets.beginBatch();int template=GpuPlayerPackets.registerTemplate(new float[192]);Matrix4f root=new Matrix4f().translation(1,2,3);int baseline=GpuPlayerPackets.addPose(root,template);NativePoseGroups groups=new NativePoseGroups();Object profile=new Object(),pass=new Object();groups.add(profile,pass,root,baseline);int basePlayers=GpuPlayerPackets.count(),basePoses=GpuPlayerPackets.explicitPoseRows(),baseGroups=groups.preparedCheckpoint();int[] baseWords=prefix("players",32),poseWords=prefix("poses",96);boolean partialBeforeReturn=false,partialGroupBeforeReturn=false;
        for(int stage=0;stage<=10;stage++){
            shrink("players","playerView",basePlayers*32);shrink("poses","poseView",basePoses*96);Counts counts=new Counts();var snapshot=new PreparedBlockState073.Counts();snapshot.save(counts);var tx=new GpuPlayerPackets.PreparedAppend();final int point=stage;tx.fault=p->{if(p==point)throw new Fault();};int groupBefore=groups.preparedCheckpoint(),job=-1;GpuPlayerPackets.beginPreparedAppend(tx);
            try{job=GpuPlayerPackets.addPreparedPose(root,template,tx);groups.addPrepared(profile,pass,root,job,tx);counts.size[0]+=19;counts.count[0]++;tx.point(7);counts.size[1]+=19;counts.count[1]++;tx.point(8);counts.batch+=2;counts.device+=2;tx.point(9);counts.recorded=true;tx.point(10);GpuPlayerPackets.commitPreparedAppend(tx);throw new IllegalStateException("Fault stage did not execute");}
            catch(Fault expectedFault){if(stage==1){ok(job==-1&&GpuPlayerPackets.count()==basePlayers+1,"Partial addPose-before-return not exercised");partialBeforeReturn=true;}if(stage==6){ok(groups.preparedCheckpoint()==baseGroups+1,"Partial group allocation not exercised");partialGroupBeforeReturn=true;}snapshot.restore(counts);groups.rollbackPrepared(groupBefore);GpuPlayerPackets.rollbackPreparedAppend(tx);}
            ok(!tx.open()&&GpuPlayerPackets.count()==basePlayers&&GpuPlayerPackets.explicitPoseRows()==basePoses&&groups.preparedCheckpoint()==baseGroups,"Allocation failure leaked pose/group reservation");ok(Arrays.equals(baseWords,prefix("players",32))&&Arrays.equals(poseWords,prefix("poses",96)),"Rollback damaged preexisting data");ok(Arrays.equals(counts.size,new int[]{19,38})&&Arrays.equals(counts.count,new int[]{1,2})&&counts.batch==3&&counts.device==3&&!counts.recorded,"Partial mirror/count/recorded publication not restored");
        }
        ok(partialBeforeReturn&&partialGroupBeforeReturn,"Missing peer allocation witnesses");
        System.out.println("{\"passed\":true,\"checks\":"+checks+",\"lateRevealReplacementChildrenZeroMask\":true,\"ownedMaterialReselected\":true,\"partialPoseBeforeReturnRolledBack\":true,\"partialGroupBeforeReturnRolledBack\":true,\"faultStages\":11,\"jobsGroupsCountsBytesRecordedRestored\":true,\"noGlCalls\":true}");
    }
}
